    while True:
        b=buf[pos]; pos+=1
        result |= (b & 0x7f) << shift
        if not (b & 0x80): break
        shift+=7
    return result, pos

def read_zv(buf, pos):
    u,pos = read_uv(buf,pos)
    return (u >> 1) ^ -(u & 1), pos

def read_value(buf, pos, ttype):
