        return struct.unpack('<d', buf[pos:pos+8])[0], pos+8
    if ttype == 8:
        l,pos = read_uv(buf,pos)
        return buf[pos:pos+l], pos+l
    if ttype == 12:
        return read_struct(buf,pos)
    if ttype == 9:
        b=buf[pos]; pos+=1
        if b & 0xF0 == 0xF0:
            size,pos = read_uv(buf,pos)
            etype = buf[pos]; pos+=1
        else:
            size = b>>4; etype = b&0x0F
