        b=buf[pos]; pos+=1
        if b==0: break
        delta=(b>>4)&0x0F; ttype=b&0x0F
        if delta==0:
            fid,pos=read_zv(buf,pos)
        else:
            fid=last+delta
        last=fid
        v,pos=read_value(buf,pos,ttype)
        fields[fid]=v
    return fields,pos

with open('/app/data.parquet','rb') as f:
    data=f.read()
assert data[:4]==b'PAR1' and data[-4:]==b'PAR1', 'bad magic'
footer_len=int.from_bytes(data[-8:-4],'little')
footer=data[len(data)-8-footer_len:len(data)-8]
fm,_=read_struct(footer,0)
print('num_rows =', fm[3])
schema=fm[2]
print('schema: %d elements' % len(schema))
for s in schema:
    print('   name=%s type=%s rep=%s children=%s conv=%s' % (s[1], s.get(2), s.get(4), s.get(5), s.get(6)))
rg=fm[4][0]
cols=rg[1]
