    type_=meta[1]; path=meta[3]
    name=path[0].decode() if isinstance(path[0],bytes) else path[0]
    comp=meta[6]
    ph,pend=read_struct(data, offset)
    dph=ph[5]; body=data[offset+pend:offset+pend+comp]
    vals=[]; p=0
    if type_==1:
        while p<len(body): vals.append(struct.unpack('<i',body[p:p+4])[0]); p+=4
    elif type_==2:
        while p<len(body): vals.append(struct.unpack('<q',body[p:p+8])[0]); p+=8
    elif type_==5:
        while p<len(body): vals.append(struct.unpack('<d',body[p:p+8])[0]); p+=8
    elif type_==6:
        while p<len(body):
            l=int.from_bytes(body[p:p+4],'little'); p+=4
            vals.append(body[p:p+l].decode()); p+=l
    else:
        raise ValueError('type %d'%type_)
    expected=[(r[idx] if idx<len(r) else '') for r in data_rows]
    ok=[str(v) for v in vals]==expected
    allok=allok and ok
